(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory(require('./fieldwork.js'),require('./engine.js'));else root.HormigonWorkbench=factory(root.HormigonFieldwork,root.Hormigon);})(typeof globalThis!=='undefined'?globalThis:this,function(F,E){
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(x,n=2)=>Number.isFinite(x)?x.toLocaleString('es-EC',{minimumFractionDigits:n,maximumFractionDigits:n}):'Sin medir';
const td=(h,rows)=>'<div class="table-scroll"><table><thead><tr>'+h.map(x=>'<th>'+esc(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
function caption(id,label,tip,lab){return '<div class="field-caption"><label for="'+esc(id)+'">'+esc(label)+'</label><button type="button" class="hint-toggle" data-hint="'+esc(id)+'" aria-label="Ayuda: '+esc(label)+'" aria-controls="tip-'+esc(id)+'" aria-expanded="false">ⓘ</button><div class="field-guide" id="tip-'+esc(id)+'">'+esc(tip)+(lab?' <button type="button" class="help-link" data-page="lab" data-focus="'+esc(lab)+'">Calcular en Laboratorio →</button>':'')+'</div></div>';}
function control(d,id,label,type,tip,fallback='',options){const v=d[id]??fallback,attr=' id="pad-'+id+'" data-pad="'+id+'" aria-describedby="tip-pad-'+id+'"';return '<div class="field">'+caption('pad-'+id,label,tip)+'<div class="input-wrap">'+(options?'<select'+attr+'>'+options.map(([k,t])=>'<option value="'+esc(k)+'" '+(String(k)===String(v)?'selected':'')+'>'+esc(t)+'</option>').join('')+'</select>':'<input'+attr+' type="'+type+'" '+(type==='number'?'step="any" inputmode="decimal"':'maxlength="300"')+' value="'+esc(v)+'">')+'</div></div>';}
const btn=(a,t)=>'<button type="button" class="primary" data-action="'+a+'">'+t+'</button>';
const section=(id,t,sub,body)=>'<section class="card" id="'+id+'"><div class="card-head"><div><h2>'+t+'</h2><p>'+sub+'</p></div><span class="badge">v1.2</span></div><div class="card-body">'+body+'</div></section>';
function today(){const now=new Date();return [now.getFullYear(),('0'+(now.getMonth()+1)).slice(-2),('0'+now.getDate()).slice(-2)].join('-');}
function records(batches){if(!batches.length)return '<p class="inline-note">Todavía no se han registrado amasadas.</p>';
 return batches.map(b=>{const q=F.summary(b),d=b.design;
 let html='<h3>'+esc(b.id)+' · '+esc(b.date)+'</h3><p>'+esc(d.name)+' · f′c '+fmt(d.fc)+' MPa · '+(d.dataMode==='demo'?'DEMOSTRACIÓN':'Pesadas declaradas por el responsable')+'</p>'+td(['Material','Previsto (kg)','Pesado (kg)','Diferencia (kg)'],q.rows.map(x=>[x.name,fmt(x.expected,3),fmt(x.actual,3),fmt(x.delta,3)]));
 html+='<p>Volumen nominal: <b>'+fmt(b.volume,4)+' m³</b>. Masa total pesada: <b>'+fmt(q.mass,3)+' kg</b>. '+(q.volume===null?'Ingresa densidad fresca al crear la amasada para obtener el rendimiento.':'Rendimiento medido = '+fmt(q.mass,3)+' kg / '+fmt(b.density,2)+' kg/m³ = <b>'+fmt(q.volume,6)+' m³</b> ('+fmt(q.relative*100,2)+' % del volumen nominal).')+'</p>';
 html+=td(['Propiedad','Objetivo del diseño','Medición','Medición − objetivo'],[['Asentamiento (mm)',fmt(d.targetSlump),fmt(b.slump),fmt(q.slumpDelta)],['Aire (%)',fmt(d.air),fmt(b.air),q.airDelta===null?'Sin medir':fmt(q.airDelta)+' p.p.']]);
 html+=b.specimens.length?'<h4>Probetas de esta amasada</h4>'+td(['Probeta','Edad (días)','Carga (kN)','Diámetro (mm)','Resistencia (MPa)'],[...b.specimens].sort((a,b)=>a.age-b.age).map(s=>[s.id,fmt(s.age),fmt(s.load),fmt(s.diameter),fmt(E.compression(s.load,s.diameter),3)])):'<p>Sin ensayos de compresión registrados para esta amasada.</p>';
 return '<article class="batch-record">'+html+'</article>';}).join('');
}
function notebook(batches,d,r,p){
 const b=(id,label,type,tip,def='')=>control(p,'b-'+id,label,type,tip,def);
 const inputs=b('id','Código de amasada','text','Usa un código único de tu cuaderno; por ejemplo, A-01.')+b('date','Fecha de preparación','date','Fecha en que preparaste la amasada.',today())+b('volume','Volumen nominal (m³)','number','Volumen previsto de esta amasada, sin volver a sumar reserva; 30 L = 0,030 m³.')+
 F.keys.map((k,i)=>b(k,'Masa de '+F.names[i].toLowerCase()+' (kg)','number','Ingresa la masa que realmente pesaste para toda esta amasada, no kg/m³.'+(k==='admixture'?' Si no se usó, ingresa 0.':''),k==='admixture'&&d.admDose===0?'0':'')).join('')+
 b('density','Densidad fresca medida (kg/m³)','number','Opcional. Se divide la masa realmente pesada entre esta densidad para obtener el volumen producido.')+
 b('slump','Asentamiento medido (mm)','number','Opcional. Anota el resultado del ensayo de esta amasada, no la meta.')+b('air','Aire medido (%)','number','Opcional. Registra el porcentaje medido; un campo vacío significa sin medir.');
 const register=section('cuaderno','Bitácora de amasadas','Compara las cantidades previstas con lo que pesaste. Cada registro conserva el diseño usado ese día.',r.ok?'<div class="fields three">'+inputs+'</div><div class="toolbar">'+btn('record-batch',d.dataMode==='demo'?'Registrar amasada de demostración':'Registrar pesadas reales')+'</div>':'<p class="inline-note">Completa la predosificación para registrar una nueva amasada.</p>');
 const specimenForm=batches.length?'<div class="fields three">'+control(p,'s-batch','Amasada de origen','text','Selecciona la amasada de la que proviene la probeta.',batches[0].id,batches.map(b=>[b.id,b.id+' · '+b.date]))+
 control(p,'s-id','Identificación de probeta','text','Copia el código único marcado en la probeta.')+control(p,'s-age','Edad al ensayo (días)','number','Ingresa la edad real al ensayar; por ejemplo, 7, 14 o 28 días.')+
 control(p,'s-diameter','Diámetro medido (mm)','number','Usa el diámetro de la probeta ensayada, no un valor nominal supuesto.')+control(p,'s-load','Carga máxima (kN)','number','Copia la carga máxima registrada por la prensa, en kN.')+'</div><div class="toolbar">'+btn('record-specimen','Vincular resultado de probeta')+'</div>':'<p class="inline-note">Primero registra la amasada de origen.</p>';
 return register+section('probetas','Seguimiento de probetas','Resistencia individual = carga / área medida. No se estima resistencia a otras edades.',specimenForm)+section('historial-amasadas','Amasadas registradas','Las diferencias orientan la revisión. El registro no aprueba resistencia ni trabajabilidad.',records(batches));
}
function library(items,d,p){let form=control(p,'m-kind','Tipo de ficha','text','Se guardan las propiedades actuales del formulario de Materiales.','fine',Object.entries(F.kinds))+control(p,'m-label','Nombre de la ficha','text','Identifica cantera, proveedor o producto; por ejemplo, Arena de cantera A.')+control(p,'m-source','Procedencia / ensayo','text','Indica proveedor, muestra, certificado o número de informe.')+control(p,'m-date','Fecha de caracterización','date','Fecha del ensayo o certificado, no la fecha de hoy salvo que coincidan.',today());
 return section('fichas','Biblioteca de materiales','Guarda propiedades caracterizadas para reutilizarlas en otros proyectos de este navegador.','<div class="fields">'+form+'</div><div class="toolbar">'+btn('store-material','Guardar ficha del material actual')+'</div><p class="tiny muted">Los áridos conservan G, base y absorción, además del MF de arena o TMN y masa unitaria de grava. Tendrás que ingresar la humedad del día al aplicarlos. El respaldo JSON incluye esta biblioteca.</p>'+(items.length?items.map((m,i)=>'<div class="material-file"><div><b>'+esc(m.label)+'</b><p>'+esc(F.kinds[m.kind])+' · '+esc(m.source)+' · '+esc(m.date)+' · '+(m.mode==='demo'?'DEMOSTRACIÓN':'Datos reales declarados')+'</p></div><button data-material="'+i+'" '+(d.dataMode==='real'&&m.mode==='demo'?'disabled':'')+'>Aplicar ficha</button></div>').join(''):'<p class="inline-note">Aún no hay fichas guardadas.</p>'));
}
function explain(a,b,ra,rb){if(!ra.ok||!rb.ok)return '<p class="inline-note">La explicación requiere dos escenarios calculables. Revisa los avisos del escenario bloqueado.</p>';
 const n=x=>fmt(x,3),cause=(d,r)=>d.minCement>r.water/r.selectedWC+1e-9?'controla el mínimo de cemento':d.maxWC>0&&d.maxWC<r.wcStrength?'controla el límite máximo de a/c':'controla la a/c por resistencia';
 const delta=(a,b)=>n(b-a),freeA=ra.fine.free+ra.coarse.free,freeB=rb.fine.free+rb.coarse.free;
 const quantity=ra.rows.reduce((s,x,i)=>s+(rb.rows[i].wet-x.wet)*x.price,0),prices=rb.rows.reduce((s,x,i)=>s+x.wet*(x.price-ra.rows[i].price),0);
 const same=Math.abs(ra.cement-rb.cement)<1e-8&&Math.abs(ra.water-rb.water)<1e-8;
 return '<div class="compare-notes"><h3>¿Por qué cambió la mezcla?</h3><p><b>Cemento.</b> A: '+n(ra.cement)+' kg/m³ ('+cause(a,ra)+'); B: '+n(rb.cement)+' kg/m³ ('+cause(b,rb)+'). Agua efectiva / a/c seleccionada: A '+n(ra.water)+' / '+fmt(ra.selectedWC,6)+'; B '+n(rb.water)+' / '+fmt(rb.selectedWC,6)+'.</p><p><b>Agua a añadir.</b> B − A = cambio del agua efectiva ('+delta(ra.water,rb.water)+') − cambio del agua libre de áridos ('+delta(freeA,freeB)+') − cambio del agua del aditivo ('+delta(ra.admixtureWater,rb.admixtureWater)+') = <b>'+delta(ra.addedWater,rb.addedWater)+' kg/m³</b>.'+(same?' La cantidad de cemento y el agua efectiva permanecen iguales.':'')+'</p><p><b>Costo.</b> Cambio por cantidades a precios de A: '+n(quantity)+' USD/m³. Cambio por precios usando cantidades de B: '+n(prices)+' USD/m³. Total: '+delta(ra.cost,rb.cost)+' USD/m³. Son diferencias aritméticas con los precios declarados.</p></div>';
}
return {caption,library,notebook,records,explain,today};
});
